def process(standardizeBeachSamples) -> pd.DataFrame:
    import pandas as pd

    df = standardizeBeachSamples.copy()

    # Swimming standard: meet if enterococcus <= 104 counts / 100 mL
    failed = df[df['enterococcus'] > 104]

    total_failed = int(len(failed))
    if total_failed == 0:
        pct = 0.0
    else:
        pct = float(failed['rainWithin24h'].mean() * 100)

    out = pd.DataFrame([
        {
            'totalFailedSamples': total_failed,
            'failedWithRainWithin24h': int(failed['rainWithin24h'].sum()),
            'percentFailedWithRainWithin24h': round(pct, 2),
        }
    ])
    return out
